async function boot(page: import('@playwright/test').Page, baseURL: string, session: ClaimResponse) {
  await page.goto(baseURL);
  await page.evaluate(
    (s) => localStorage.setItem('drift.session.v1', JSON.stringify(s)),
    session,
  );
  await page.goto(`${baseURL}/?sys=${session.homeSystemId}`);
  // The home-docked ship boots with the docked HUD stubs.
  await expect(page.locator('#docked-indicator')).toBeVisible({ timeout: 20_000 });
}

